import type { CSSProperties } from "react";
import temple from "./temple-triangles.json";

/** Geometry generated by fogleman/primitive, not a procedural approximation.
 * Kept server-rendered so the triangle dataset is not in the client bundle.
 * Original source and exact generation command are recorded in the JSON.
 */
export function TempleArt() {
  // Keep just eight ambient layers as detail grows, and the same short reveal.
  const layerCount = 8;
  const trianglesPerLayer = Math.ceil(temple.triangles.length / layerCount);
  const revealStaggerMs = 2240 / Math.max(temple.triangles.length - 1, 1);
  return (
    <svg
      viewBox={`0 0 ${temple.width} ${temple.height}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      focusable="false"
      aria-hidden="true"
    >
      <rect
        width={temple.width}
        height={temple.height}
        fill={temple.background}
      />
      <g transform={temple.transform}>
        {Array.from({ length: layerCount }, (_, group) => (
          <g
            key={group}
            className="temple-layer"
            style={
              {
                "--drift-delay": `${group * -2.1}s`,
                "--drift-duration": `${18 + group * 2}s`,
              } as CSSProperties
            }
          >
            {temple.triangles
              .slice(group * trianglesPerLayer, (group + 1) * trianglesPerLayer)
              .map((triangle, index) => (
                <polygon
                  key={index}
                  points={triangle.points}
                  fill={triangle.fill}
                  fillOpacity={triangle.opacity}
                  className="temple-facet"
                  style={
                    {
                      "--facet-delay": `${Math.round((group * trianglesPerLayer + index) * revealStaggerMs)}ms`,
                      "--facet-x": `${((index % 3) - 1) * 3}px`,
                      "--facet-y": `${((index % 5) - 2) * 2}px`,
                    } as CSSProperties
                  }
                />
              ))}
          </g>
        ))}
      </g>
    </svg>
  );
}
